package calc

import "strconv"

// 0x51dde0 item_use_power_selection(c, inst, pcost): a party member uses item
// instance inst (record [0x68516c]+id*0x10d). It returns the 0x51ee70 result
// (or 1 for the special item 0x29f, 0 when refused), and writes the action
// cost to *pcost: -1 by default, 10 for a non-scroll item whose kind maps to
// skill 9 (table 0x616e84), spell level*8+20 for scrolls and potions (class 0xd /
// 0xe), 0 when 0x51ee70 fails or 0x4d9080 vetoes. Scrolls and potions pick the
// power level downward from 7 while the 0x51dcd0 risk stays below 16, then roll
// R(100) against 7*level per level. Usability 0x51d610 / 0x51d800 (D4), the
// cast 0x51ee70 (D4), the charge use 0x51e760 (D4), skill training 0x553f10 (D4),
// the script dispatcher 0x506670 (D4) and 0x4d9080, 0x52e690, 0x58aad0, 0x58b410,
// 0x58ac00, 0x408860, 0x506280 (排除) are address stubs; F runs itemCast and the
// 0x51d610 / 0x51d800 nodes on the same world (iupCallees). 0x5061a0 (fact set
// with the 0x5588f0 event log and 0x5289b0 queue), 0x50b800, 0x538670, 0x53be00,
// 0x53be50, 0x590950 and the 0x68c108 name cache run natively.

const (
	iupSpecial = 0x29f // the item id handled by the fact path
	iupSkill9  = 9     // skill id of table 0x616e84 that costs 10
)

func iupAssert(line uint32) {
	spcPanic("51dde0 srAssertFail line 0x" + strconv.FormatUint(uint64(line), 16))
}

// iupD4 is an address-stubbed D4 callee: Emu replays the case stub, F runs the
// callee node when its case layout is in iupCallees.
func iupD4(w *spcWorld, a uint32, args ...uint32) uint32 {
	k := w.call(a, args...)
	if c := iupCallees[a]; w.real && c != nil {
		return marCall(w.mcaWorld, c, args)
	}
	return w.replay(a, k, args...)
}

// iupCast is 0x51ee70(c, inst, PL). F runs itemCast, whose used-level out is
// the third argument slot: here that slot holds pcost, so it is saved around.
func iupCast(w *spcWorld, c, inst, pl, pcost uint32) uint32 {
	k := w.call(0x51ee70, c, inst, pl)
	if !w.real {
		return w.replay(0x51ee70, k, c, inst, pl)
	}
	slot := uint32(mstStackBase + 4 + 4*2)
	w.put32(slot, pl)
	r := w.itemCast(c, inst, pl)
	w.put32(slot, pcost)
	return r
}

// iupNpc is 0x50b800(i): the NPC record of list [0x689f94] (entry 0 past the
// count), 0 when absent or flagged +0xc7.
func iupNpc(w *spcWorld, i uint32) uint32 {
	l := w.u32(0x689f94)
	if l == 0 {
		return 0
	}
	p := w.u32(w.u32(l + 0xc))
	if int32(i) < int32(w.u32(l+4)) {
		p = w.u32(w.u32(l+0xc) + 4*i)
	}
	if p == 0 || w.u8(p+0xc7) != 0 {
		return 0
	}
	return p
}

// iupGrow appends entry e (n dwords) to the vector at cnt/capa/buf, growing it
// to exactly cnt+1 entries through the heap (0x5e1ce0) when full.
func iupGrow(w *spcWorld, cnt, capa, buf uint32, e ...uint32) {
	n := uint32(len(e))
	c := int32(w.u32(cnt))
	if c+1 > int32(w.u32(capa)) {
		nb := w.alloc(uint32(c+1) * n * 4)
		old := w.u32(buf)
		for i := uint32(0); int32(i) < c; i++ {
			for j := uint32(0); j < n; j++ {
				w.put32(nb+4*(n*i+j), w.u32(old+4*(n*i+j)))
			}
		}
		w.put32(buf, nb)
		w.put32(capa, uint32(c+1))
	}
	for j, v := range e {
		w.put32(w.u32(buf)+4*(n*uint32(c)+uint32(j)), v)
	}
	w.put32(cnt, uint32(c+1))
}

// iupFact is 0x5061a0(id, v, 0): set fact byte 0x689b78+id; a change logs it
// (0x5588f0) and may raise the journal notice; then 0x506670(id, v) runs.
func iupFact(w *spcWorld, id, v uint32) {
	if int32(id) > 0x3e8 {
		return
	}
	old := uint32(w.u8(0x689b78 + id))
	w.put8(0x689b78+id, byte(v))
	below := int32(id) < int32(w.u32(0x683f8c))
	if old != v {
		iupLog(w, id, below)
	}
	iupD4(w, 0x506670, id, v)
	if w.u8(0x688290) != 0 {
		w.stub(0x58aad0, 5, 0x619a38, w.u32(0x6836ac)+id*0x1d8+4, 0, 0)
	}
}

// iupLog is 0x5588f0(id): event log entry {map, id, flag byte} (0x558820
// creates the log), then the journal notice for levels at or below the
// difficulty threshold.
func iupLog(w *spcWorld, id uint32, below bool) {
	if w.u32(0x68de40) == 0 { // 0x558820
		s := w.alloc(0x10)
		w.put32(s, 0x5ee8a0)
		w.put32(s+4, 0)
		w.put32(s+8, 5)
		w.put32(s+0xc, w.alloc(0x3c))
		w.put32(0x68de40, s)
	}
	m := w.u32(0x686a70)
	flag := w.stub(0x506280, id) & 0xff
	if below {
		flag |= 0x506100 // stack residue: return address 0x5061f1 of 0x5061a0's sprintf call
	}
	s := w.u32(0x68de40)
	iupGrow(w, s+4, s+8, s+0xc, m, id, flag)
	if w.u8(0x68de44) != 0 {
		return
	}
	thr := int32(id)
	switch w.u32(0x6850d5) {
	case 0:
		thr = 2
	case 1:
		thr = 1
	case 2:
		thr = 0
	}
	lv := w.u32(0x6836ac) + id*0x1d8
	if int32(int8(w.u8(lv+0x37))) > thr {
		return
	}
	n := w.u16(lv + 0x100)
	if w.stub(0x506280, id)&0xff != 0 {
		n = w.u16(lv + 0x38)
	}
	ui := w.u32(0x68edcc)
	if n == 0 || ui == 0 {
		return
	}
	if w.u8(0x683f97) != 0 { // 0x5289b0(8, 0)
		msg := w.alloc(0x24)
		for i := uint32(0); i < 9; i++ {
			w.put32(msg+4*i, 0)
		}
		w.put32(msg, 0xffffffff)
		w.put32(msg+0xc, 8)
		w.put32(msg+0x20, w.u32(0x68c4ac))
		iupGrow(w, 0x68c4c0, 0x68c4c4, 0x68c4c8, msg)
		return
	}
	w.stub(0x58ac00, 3, w.u32(w.u32(0x68c09c)+0x1d28), 2, w.u32(ui+0x2d4)-w.u32(ui+0x2cc), 0) // 0x58fb30
	w.stub(0x408860, 0x61c5cc, 0)
}

func (w *spcWorld) iupItemUse(c, inst, pcost uint32) uint32 {
	idx := w.ieIndex(c)
	id := w.u32(inst)
	if id >= ieItems && id != iupSpecial {
		spcPanic("51dde0 item id past the fixture item records")
	}
	r := w.u32(0x68516c) + id*0x10d
	cost, ret := uint32(0xffffffff), c
	name := func() {
		if w.u8(inst+6) == 0 {
			w.ieName(r)
		}
	}
	if byte(iupD4(w, 0x51d610, c, id)) == 0 {
		name()
		w.notice(idx) // 0x590950 string 0x590
		w.put32(pcost, 0xffffffff)
		return 0
	}
	if byte(iupD4(w, 0x51d800, c, inst)) == 0 {
		name()
		w.notice(idx) // string 0x594
		w.put32(pcost, cost)
		return ret
	}
	if use := w.u8(r + 0x66); (use == 2 || use == 4) && w.u8(inst+5) == 0 {
		name()
		w.notice(idx) // string 0x7c4 / 0x7c8
		v := w.u32(0x68c558)
		if use == 4 {
			v = w.u32(0x5ee624)
		}
		w.stub(0x52e690, w.charBase(idx), v, 0, w.u32(0x5ed8cc), w.u32(0x5ed914))
		w.put32(pcost, cost)
		return ret
	}
	cls := w.u8(r + 0x3e)
	if cls == 0xd && w.u32(w.u32(0x685174)+0xa21+idx*0x1862) != 0 {
		w.notice(idx) // string 0x598
		w.put32(pcost, cost)
		return ret
	}
	spell := uint32(w.u8(r + 0x63))
	kind := uint32(w.u8(r + 0x42))
	if id == iupSpecial {
		npc := iupNpc(w, w.u32(w.u32(0x685178)+0xfa+idx*0x106))
		if npc == 0 {
			iupAssert(0x89d)
		}
		if w.u8(npc+0x2e) != 0x20 {
			iupAssert(0x89e)
		}
		iupFact(w, 0x44, 1)
		iupFact(w, 0x284, 0)
		iupD4(w, 0x51e760, c, inst, 1)
		return 1
	}
	var pl uint32
	if cls != 0xd && cls != 0xe {
		if spell != 0x58 && spell != 0x74 && w.u32(0x616e84+4*kind) == iupSkill9 {
			cost = 10
		}
		pl = uint32(w.u8(r + 0x64))
	} else {
		skill := uint32(0xffffffff)
		if spell != 0x58 && spell != 0x74 {
			if kind >= 12 {
				spcPanic("51dde0 item kind past the 12-entry skill table 0x616e84")
			}
			skill = w.u32(0x616e84 + 4*kind)
		}
		cost = w.u32(w.spellRecord(spell)+0x56)*8 + 0x14
		v := w.u32(c + skill*0x26 + 0x1a3)
		for pl = 7; pl > 0 && w.ieRisk(c, skill, v, spell, pl) >= 0x10; pl-- {
		}
		for thr := 7 * pl; pl > 0 && thr > uint32(w.r.R(100)); thr -= 7 { // 0x40efa0
			pl--
		}
		if pl == 0 {
			name()
			w.notice(idx) // string 0x7cc
			iupD4(w, 0x553f10, c, skill, 1, 0)
			w.put32(pcost, cost)
			return ret
		}
	}
	local := w.local(0x34)
	marCharSource(w.mcaWorld, idx, local)
	if cls == 0x10 || cls == 0x15 || cls == 0x16 {
		t := w.u32(0x685178) + idx*0x106 + 0x1d
		if w.u8(0x683f94) != 0 { // 0x538670(idx, idx, 0): the slot targets its own character
			for i, x := range [8]uint32{1, idx, 0xffffffff, 0xffffffff} {
				w.put32(t+4*uint32(i), x)
			}
		} else if k := w.u32(t); k == 1 {
			marCharSource(w.mcaWorld, w.u32(t+4), local)
		} else if k == 3 {
			marMonSource(w.mcaWorld, w.findMonster(w.u32(t+8)), local)
		}
	}
	if kind >= 10 {
		iupAssert(0x906)
	}
	if spell != 0 && cls != 0xe && (cls < 0x15 || cls > 0x16) && byte(w.stub(0x4d9080, 0, 4, 1)) != 0 {
		w.put32(pcost, 0)
		return 0
	}
	switch {
	case w.isChar(local):
		name()
		w.notice(w.u32(local + 4))
	case w.isMon(local):
		m := w.findMonster(w.u32(local + 8))
		item := r
		if w.u8(inst+6) == 0 {
			item = w.ieName(r)
		}
		w.stub(0x58aad0, 9, 0x61aa28, w.name(m), w.u32(w.u32(0x68c09c)+4*w.u16(0x61e956+4*kind)), item)
	default:
		iupAssert(0x924)
	}
	if w.u8(0x68510c) == 0 {
		w.put8(0x69b7b8, 1) // 0x5905c0(1, -1)
	}
	if spell == 0 {
		iupAssert(0x934)
	}
	if res := iupCast(w, c, inst, pl, pcost); res == 0 {
		cost, ret = 0, 0
	} else {
		iupD4(w, 0x51e760, c, inst, 1)
		ret = res
	}
	w.put32(pcost, cost)
	return ret
}

func iupBody(w *mcaWorld) {
	s := &spcWorld{mcaWorld: w}
	w.tab = iupStubs
	s.put(mstRet, 4, uint64(s.iupItemUse(s.arg(0), s.arg(1), s.arg(2))))
}

func itemUsePowerSelectionNode(in []int64, r Rand) []int64 {
	return mcaRun(&iupSpec, true, iupBody)(in, r)
}

func iupEmu(in []int64, r Rand) []int64 { return mcaRun(&iupSpec, false, iupBody)(in, r) }

func init() {
	Nodes["0051dde0"] = Node{Addr: "0051dde0", In: iupIn, Out: iupOut, F: itemUsePowerSelectionNode, Emu: iupEmu}
}

